head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.notiId;
scwin.vSecugrpID = "";
scwin.strBzProcsNo;
scwin.vScrenID = "ULDSTF20502_FILELIST.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_read = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=REALINVSTG_ATTACHFILE_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.realinvstgCorp.attachfile" + "&{P}param01=" + scwin.strBzProcsNo;
    dts_fileList.DataID = encodeURI(url);
    dts_fileList.Reset();
    if (dts_fileList.getTotalRow() == 0) {
        $c.win.alert("등록된 첨부파일이 없습니다.");
    }
};



//파일 다운로드
scwin.fn_filedown = function(attach_seq) {
    if (dts_fileList.getCellData(1, "FILE_SIZE") == 0) {
        $c.win.alert("실제 파일이 존재하지 않습니다.");
    } else {
        location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&file_id=" + scwin.strBzProcsNo + "&attach_seq=" + attach_seq + "&gubun=31";
    }
};
scwin.grd_userlist_OnDblClick = function(row, colid) {
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0) {
        $c.elw.fn_filedown(dts_fileList.getCellData(row, "SEQ"));
    }
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame(); //self.close();

};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    scwin.strBzProcsNo = $c.stf.getQuery(frame.srcUrl, "BZ_PROCS_NO");
    scwin.fn_read();
};
